
import json, os, subprocess, sys, time, glob
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "-U", "diffusers>=0.42", "transformers", "accelerate"], check=False)
TMP, OUT = "/tmp/zimg", "/kaggle/working/candidates"
os.makedirs(TMP, exist_ok=True); os.makedirs(OUT, exist_ok=True)
json.dump(json.loads('[{"cell": "c069", "cand": 0, "seed": 16902, "light": "top", "gender": "female", "age": "middle-aged", "people": "East Asian", "pose": "three-quarter", "hair": "short bob haircut", "extra": "wearing thin-rimmed glasses", "prompt": "Dramatic chiaroscuro portrait lit by a single hard light from directly above the head (overhead top lighting). The top of the head, the forehead, the nose bridge and the cheekbones are lit; the eye sockets, the areas under the nose and under the lips, the chin and the neck are in deep black shadow. Close-up studio photograph of a middle-aged East Asian woman with short bob haircut, wearing thin-rimmed glasses, head turned in a three-quarter view, neutral expression, wearing a plain black shirt, the head filling most of the frame. Pure black background, no fill light, no rim light, the light source itself is outside the frame, extreme contrast, photorealistic, sharp focus, 85mm lens.", "file": "c069_2.png"}, {"cell": "c069", "cand": 1, "seed": 16903, "light": "top", "gender": "female", "age": "middle-aged", "people": "East Asian", "pose": "three-quarter", "hair": "short bob haircut", "extra": "wearing thin-rimmed glasses", "prompt": "Dramatic chiaroscuro portrait lit by a single hard light from directly above the head (overhead top lighting). The top of the head, the forehead, the nose bridge and the cheekbones are lit; the eye sockets, the areas under the nose and under the lips, the chin and the neck are in deep black shadow. Close-up studio photograph of a middle-aged East Asian woman with short bob haircut, wearing thin-rimmed glasses, head turned in a three-quarter view, neutral expression, wearing a plain black shirt, the head filling most of the frame. Pure black background, no fill light, no rim light, the light source itself is outside the frame, extreme contrast, photorealistic, sharp focus, 85mm lens.", "file": "c069_3.png"}, {"cell": "c069", "cand": 2, "seed": 16904, "light": "top", "gender": "female", "age": "middle-aged", "people": "East Asian", "pose": "three-quarter", "hair": "short bob haircut", "extra": "wearing thin-rimmed glasses", "prompt": "Dramatic chiaroscuro portrait lit by a single hard light from directly above the head (overhead top lighting). The top of the head, the forehead, the nose bridge and the cheekbones are lit; the eye sockets, the areas under the nose and under the lips, the chin and the neck are in deep black shadow. Close-up studio photograph of a middle-aged East Asian woman with short bob haircut, wearing thin-rimmed glasses, head turned in a three-quarter view, neutral expression, wearing a plain black shirt, the head filling most of the frame. Pure black background, no fill light, no rim light, the light source itself is outside the frame, extreme contrast, photorealistic, sharp focus, 85mm lens.", "file": "c069_4.png"}, {"cell": "c069", "cand": 3, "seed": 16905, "light": "top", "gender": "female", "age": "middle-aged", "people": "East Asian", "pose": "three-quarter", "hair": "short bob haircut", "extra": "wearing thin-rimmed glasses", "prompt": "Dramatic chiaroscuro portrait lit by a single hard light from directly above the head (overhead top lighting). The top of the head, the forehead, the nose bridge and the cheekbones are lit; the eye sockets, the areas under the nose and under the lips, the chin and the neck are in deep black shadow. Close-up studio photograph of a middle-aged East Asian woman with short bob haircut, wearing thin-rimmed glasses, head turned in a three-quarter view, neutral expression, wearing a plain black shirt, the head filling most of the frame. Pure black background, no fill light, no rim light, the light source itself is outside the frame, extreme contrast, photorealistic, sharp focus, 85mm lens.", "file": "c069_5.png"}]'), open(os.path.join(TMP, "rows.json"), "w"))
open(os.path.join(TMP, "worker.py"), "w").write('\nimport json, os, sys, time\nos.environ.setdefault("PYTORCH_CUDA_ALLOC_CONF", "expandable_segments:True")\nimport torch\nfrom diffusers import AutoencoderKL, ZImagePipeline\nMODEL = "Tongyi-MAI/Z-Image-Turbo"\nTMP, OUT = "/tmp/zimg", "/kaggle/working/candidates"\nROWS = json.load(open(os.path.join(TMP, "rows.json")))\nSIZE = int(os.environ["GEN_SIZE"])\nmode = sys.argv[1]\n\nif mode == "encode":\n    pipe = ZImagePipeline.from_pretrained(MODEL, torch_dtype=torch.bfloat16, transformer=None, vae=None)\n    pipe.text_encoder.to("cuda")\n    emb = {}\n    with torch.no_grad():\n        for r in ROWS:\n            pe, _ = pipe.encode_prompt(prompt=r["prompt"], device="cuda", do_classifier_free_guidance=False)\n            emb[r["file"]] = [e.to("cpu") for e in pe]\n    torch.save(emb, os.path.join(TMP, "emb.pt"))\n    print("encoded", len(emb), flush=True)\n    sys.exit(0)\n\ng, n = int(sys.argv[2]), int(sys.argv[3])\nemb = torch.load(os.path.join(TMP, "emb.pt"))\npipe = ZImagePipeline.from_pretrained(MODEL, torch_dtype=torch.bfloat16, text_encoder=None, tokenizer=None)\npipe.to("cuda")\npipe.vae.enable_tiling()\ncpu_vae = AutoencoderKL.from_pretrained(MODEL, subfolder="vae", torch_dtype=torch.float32)\nopen(os.path.join(TMP, f"ready{g}"), "w").write("1")\nprint(f"worker {g} ready", flush=True)\n\ndef decode(lat):\n    z = lat.to(pipe.vae.dtype) / pipe.vae.config.scaling_factor + pipe.vae.config.shift_factor\n    try:\n        with torch.no_grad():\n            x = pipe.vae.decode(z, return_dict=False)[0]\n    except torch.OutOfMemoryError:\n        torch.cuda.empty_cache()\n        z = lat.float().cpu() / cpu_vae.config.scaling_factor + cpu_vae.config.shift_factor\n        with torch.no_grad():\n            x = cpu_vae.decode(z, return_dict=False)[0]\n    return pipe.image_processor.postprocess(x.float().cpu(), output_type="pil")[0]\n\nmeta, fails = [], 0\nfor r in ROWS[g::n]:\n    path = os.path.join(OUT, r["file"])\n    if os.path.exists(path):\n        continue\n    t = time.time()\n    try:\n        with torch.no_grad():\n            lat = pipe(prompt_embeds=[e.to("cuda") for e in emb[r["file"]]], height=SIZE, width=SIZE, num_inference_steps=9,\n                       guidance_scale=0.0, output_type="latent",\n                       generator=torch.Generator("cpu").manual_seed(int(r["seed"]))).images\n        img = decode(lat)\n    except Exception as e:\n        fails += 1\n        print(f"worker {g} FAILED {r[\'file\']}: {repr(e)[:200]}", flush=True)\n        if fails >= 3 and not meta:\n            sys.exit(f"worker {g}: first images failed")\n        continue\n    img.save(path)\n    meta.append(dict(r, sec=round(time.time() - t, 1)))\n    json.dump(meta, open(os.path.join(TMP, f"meta{g}.json"), "w"), indent=1)\n    print(f"worker {g}: {r[\'file\']} {time.time() - t:.0f}s ({len(meta)})", flush=True)\n')
env = dict(os.environ, GEN_SIZE="768")
t0 = time.time()
import torch
ngpu = torch.cuda.device_count()
print("GPUs:", ngpu, flush=True)
r = subprocess.run([sys.executable, os.path.join(TMP, "worker.py"), "encode"], env=dict(env, CUDA_VISIBLE_DEVICES="0"))
if r.returncode:
    sys.exit("prompt encoding failed")
print(f"encoding done {time.time() - t0:.0f}s", flush=True)
procs = []
for g in range(ngpu):
    procs.append(subprocess.Popen([sys.executable, os.path.join(TMP, "worker.py"), "work", str(g), str(ngpu)],
                                  env=dict(env, CUDA_VISIBLE_DEVICES=str(g))))
    while not os.path.exists(os.path.join(TMP, f"ready{g}")) and procs[-1].poll() is None:
        time.sleep(5)                       # stagger the loads: one 12 GB model in RAM at a time
codes = [p.wait() for p in procs]
meta = []
for f in sorted(glob.glob(os.path.join(TMP, "meta*.json"))):
    meta += json.load(open(f))
json.dump(meta, open(os.path.join(OUT, "meta.json"), "w"), indent=1)
print("worker exit codes", codes, "| images:", len(meta), f"| {time.time() - t0:.0f}s")
if not meta:
    sys.exit("no image was generated")
